function u37Voice(id){let h=7;for(const c of String(id||''))h=(h*31+c.charCodeAt(0))>>>0;const j=(h%97)/97;
  let f=U37_KID.has(id)?300+j*50:U37_F.has(id)?200+j*50:120+j*40;if(U37_OLD.has(id))f*=.8;return {f,wave:U37_OLD.has(id)?'triangle':'square',j};}
const U37S={
  latch(){A.tone(260,.06,'square',.05,{slide:180,filter:['lowpass',900]});A.hiss(.05,.12,'bandpass',1400,{q:2});A.tone(150,.09,'sine',.12,{delay:.05,slide:90});},
  knock(){A.tone(200,.08,'sine',.16,{slide:110});A.hiss(.04,.1,'bandpass',1100,{q:1});},
  leaf(){A.hiss(.22,.05,'highpass',3400,{});A.hiss(.12,.035,'bandpass',2200,{q:1,delay:.09});},
  tick(){A.tone(1800,.025,'square',.025,{filter:['lowpass',3000]});A.hiss(.02,.05,'highpass',4000,{});}};
// talk: the line types out with a soft voice under it; a tap on the line shows it all at once
{const css=document.createElement('style');css.textContent='#talkLine.u37typing .u37c{visibility:hidden}#talkLine .u37c.on{visibility:visible}';document.head.appendChild(css);}
U37.typ={t:0,done:null};
function u37Type(id,quiet){const box=$('talkLine');if(!box)return;clearInterval(U37.typ.t);if(U37.typ.done)U37.typ.done=null;
  const tw=document.createTreeWalker(box,NodeFilter.SHOW_TEXT);const nodes=[];while(tw.nextNode())nodes.push(tw.currentNode);
  const spans=[];for(const n of nodes){if(!n.nodeValue)continue;const f=document.createDocumentFragment();for(const ch of n.nodeValue){const s=document.createElement('span');s.className='u37c';s.textContent=ch;f.appendChild(s);spans.push(s);}n.replaceWith(f);}
  if(!spans.length)return;const v=u37Voice(id);let i=0,k=0;
  const end=()=>{clearInterval(U37.typ.t);spans.forEach(s=>s.classList.add('on'));box.classList.remove('u37typing');U37.typ.done=null;};
  const step=()=>{if(!spans[0].isConnected||$('talk').hidden){end();return;}
    for(let n=0;n<3&&i<spans.length;n++){const s=spans[i++];s.classList.add('on');if(!quiet&&/[a-z0-9]/i.test(s.textContent)&&(k++%4===0))
      A.tone(v.f*(1+(((k*7)%5)-2)*.035),.05,v.wave,.018,{filter:['lowpass',1500]});}
    if(i>=spans.length)end();};
  box.classList.add('u37typing');U37.typ.done=end;U37.typ.t=setInterval(step,26);}
