// hearts as drawn hearts
function u37Hearts(root){if(!root)return;const tw=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const hit=[];let n;while((n=tw.nextNode()))if(/[♥♡]{3,}/.test(n.nodeValue))hit.push(n);
  for(const t of hit){const m=t.nodeValue.match(/([♥♡]{3,})/);const run=m[1];const sp=document.createElement('span');sp.className='u37hearts';sp.title=run.split('').filter(c=>c==='♥').length+' of '+run.length+' hearts';
    sp.innerHTML=[...run].map(c=>c==='♥'?U37_ICON.heart:U37_ICON.heart0).join('');const after=t.splitText(t.nodeValue.indexOf(run));after.nodeValue=after.nodeValue.slice(run.length);after.before(sp);}}
